import { test, expect } from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';
import { createServer } from 'node:http';

// The edge serves the single NexusNXS AI document (generated by sync-ai-shell)
// with its own nonce CSP; the local service is offline here (readyz 503).
let server, origin;
test.beforeAll(async () => {
  const { default: worker } = await import('../../dist/server/index.js');
  const shell = await worker.fetch(new Request('https://ai.nexusnxs.com/', { headers: { accept: 'text/html' } }), {
    ASSETS: { fetch: async () => new Response('', { status: 404 }) },
  }, { waitUntil() {}, passThroughOnException() {} });
  const headers = { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store',
    'Content-Security-Policy': shell.headers.get('content-security-policy'), 'Permissions-Policy': shell.headers.get('permissions-policy') };
  const html = await shell.text();
  server = createServer((request, response) => {
    const url = new URL(request.url, 'http://localhost');
    if (url.pathname === '/') { response.writeHead(200, headers); response.end(html); }
    else if (url.pathname === '/readyz') { response.writeHead(503, { 'Content-Type': 'application/json' }); response.end('{"status":"offline","retryAfter":8}'); }
    else if (url.pathname.startsWith('/api/')) { response.writeHead(503, { 'Content-Type': 'application/json' }); response.end('{"error":"Servizio momentaneamente non disponibile"}'); }
    else { response.writeHead(404); response.end(); }
  });
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  origin = `http://127.0.0.1:${server.address().port}`;
});
test.afterAll(async () => {
  server.closeAllConnections();
  await new Promise(resolve => server.close(resolve));
});

async function open(page, viewport) {
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  page.on('console', message => { if (/Content Security Policy|Refused to/i.test(message.text())) errors.push(message.text()); });
  await page.setViewportSize(viewport);
  await page.goto(origin);
  await expect(page.locator('.app .stage .composer')).toBeVisible();
  await expect.poll(() => page.locator('canvas.core').getAttribute('data-backend')).toMatch(/^(webgpu|canvas)$/);
  return errors;
}

for (const viewport of [{ width: 320, height: 568 }, { width: 844, height: 390 }, { width: 1440, height: 900 }]) {
  test(`single AI app renders under the edge CSP at ${viewport.width}`, async ({ page }) => {
    await page.emulateMedia({ reducedMotion: viewport.width === 844 ? 'reduce' : 'no-preference' });
    const errors = await open(page, viewport);
    await expect(page.getByRole('heading', { name: /Cosa creiamo\?/ })).toBeVisible();
    await expect(page.getByRole('status').first()).toContainText(/Offline|In preparazione|Connessione/);
    expect(await page.evaluate(() => document.documentElement.scrollWidth > innerWidth)).toBe(false);
    // No classic shell and no visible scrollbars in the conversation area.
    await expect(page.locator('#coreCanvas, #prompt, .shell')).toHaveCount(0);
    expect(await page.locator('.scroll').evaluate(element => getComputedStyle(element).scrollbarWidth)).toBe('none');
    const audit = await new AxeBuilder({ page }).withTags(['wcag2a', 'wcag2aa', 'wcag21aa']).analyze();
    expect(audit.violations.map(item => `${item.id}: ${item.nodes.length}`)).toEqual([]);
    expect(errors).toEqual([]);
  });
}

test('sidebar hides on wide screens, persists, and the command palette opens with the keyboard', async ({ page }) => {
  await open(page, { width: 1440, height: 900 });
  await page.getByRole('button', { name: /Nascondi barra laterale/ }).click();
  await expect(page.locator('.app')).toHaveAttribute('data-collapsed', 'true');
  await page.reload();
  await expect(page.locator('.app')).toHaveAttribute('data-collapsed', 'true');
  await page.keyboard.press('Control+b');
  await expect(page.locator('.app')).toHaveAttribute('data-collapsed', 'false');
  await page.keyboard.press('Control+k');
  await expect(page.getByRole('dialog')).toBeVisible();
  await page.keyboard.press('Escape');
  await expect(page.getByRole('dialog')).toHaveCount(0);
});

test('the desktop update feed only exposes the signed preview files and redirects binaries to the release', async () => {
  const { default: worker } = await import('../../dist/server/index.js');
  const call = (path, method = 'GET') => worker.fetch(new Request(`https://nexusnxs.com/updates/preview/${path}`, { method }), {
    ASSETS: { fetch: async () => new Response('', { status: 404 }) },
  }, { waitUntil() {}, passThroughOnException() {} });
  for (const path of ['../secrets', 'config.json', 'NexusNXS-0.3.36-Setup.exe%2F..', 'latest.yml?x=1'.replace('?x=1', '/x')]) {
    expect((await call(path)).status).toBe(404);
  }
  expect((await call('latest.yml', 'POST')).status).toBe(404);
  const binary = await call('NexusNXS-9.9.9-Setup.exe');
  expect(binary.status).toBe(302);
  expect(binary.headers.get('location')).toMatch(/^https:\/\/github\.com\/lapob\/nexus-ai\/releases\/download\/v\d+\.\d+\.\d+-preview\.\d+\/NexusNXS-9\.9\.9-Setup\.exe$/);
});

test('anonymous update health stops serving the manifest after too many crashes, one vote per source', async () => {
  const { default: worker } = await import('../../dist/server/index.js');
  const { default: release } = await import('../../app/data/public-release.json', { with: { type: 'json' } });
  const version = String(release.tag).replace(/^v/, '').replace(/-preview\.\d+$/, '');
  const rows = new Map();
  // D1 minimale in memoria: solo le tre istruzioni usate dal worker.
  const db = { prepare: (sql) => ({ bind: (...values) => ({
    run: async () => {
      if (sql.startsWith('INSERT')) { const key = values.slice(0, 3).join('|'); if (!rows.has(key)) rows.set(key, { version: values[0], event: values[1], day: values[3] }); }
      if (sql.startsWith('DELETE')) for (const [key, row] of rows) if (row.day < values[0]) rows.delete(key);
    },
    all: async () => {
      const counts = {};
      for (const row of rows.values()) if (row.version === values[0]) counts[row.event] = (counts[row.event] || 0) + 1;
      return { results: Object.entries(counts).map(([event, n]) => ({ event, n })) };
    }
  }) }) };
  const env = { ASSETS: { fetch: async () => new Response('', { status: 404 }) }, UPDATE_HEALTH: db };
  const post = (body, ip = '203.0.113.1', type = 'application/json') => worker.fetch(new Request('https://nexusnxs.com/updates/preview/health', {
    method: 'POST', body: typeof body === 'string' ? body : JSON.stringify(body), headers: { 'content-type': type, 'cf-connecting-ip': ip }
  }), env, { waitUntil() {}, passThroughOnException() {} });
  expect((await worker.fetch(new Request('https://nexusnxs.com/updates/preview/health'), env, { waitUntil() {}, passThroughOnException() {} })).status).toBe(405);
  expect((await post({ version: '9.9.9', channel: 'preview', event: 'crash' })).status).toBe(422);
  expect((await post({ version, channel: 'preview', event: 'other' })).status).toBe(422);
  expect((await post('x'.repeat(300))).status).toBe(413);
  expect((await post({ version, channel: 'preview', event: 'crash' }, '1.1.1.1', 'text/plain')).status).toBe(415);
  for (let i = 0; i < 3; i += 1) expect((await post({ version, channel: 'preview', event: 'crash' }, '198.51.100.7')).status).toBe(204);
  expect(rows.size).toBe(1);
  for (let i = 0; i < 5; i += 1) await post({ version, channel: 'preview', event: 'crash' }, `198.51.100.${20 + i}`);
  await post({ version, channel: 'preview', event: 'healthy' }, '198.51.100.90');
  const manifest = await worker.fetch(new Request('https://nexusnxs.com/updates/preview/release-manifest.json'), env, { waitUntil() {}, passThroughOnException() {} });
  expect(manifest.status).toBe(503);
  expect(manifest.headers.get('x-nexusnxs-rollout')).toBe('halted');
  expect([...rows.keys()].every((key) => /^[^|]+\|(crash|healthy)\|[0-9a-f]{8}$/.test(key))).toBe(true);
});

test('with the PC offline nothing is sent: the draft stays and the composer explains why', async ({ page }) => {
  await open(page, { width: 390, height: 844 });
  await expect(page.locator('.composer[data-offline="true"]')).toBeVisible();
  const box = page.getByRole('textbox', { name: 'Messaggio' });
  await box.fill('Ciao');
  await page.keyboard.press('Enter');
  await expect(page.locator('.thread .message.user')).toHaveCount(0);
  await expect(box).toHaveValue('Ciao');
  await expect(page.getByRole('button', { name: /Invio non disponibile/ })).toBeDisabled();
});
